        "System" => "#f0f0f5",
        _ => "#ffffff"
    };

    private string TextColor => _theme switch
    {
        "Dark" => "#cdd6f4",
        _ => "#333333"
    };

    private string FontSizeValue => _fontSize switch
    {
        "Small" => "12px",
        "Large" => "18px",
        _ => "14px"
    };
}

